# 本文件按照情绪效价 (Valence, V+/V-) 与张力 (Tension, T+/T-) 的四个象限划分，
# 包含坐标原点基准及各项动态增减条件的代表性案例，规范 Charlotte 从容大姐姐的语感、轻幽默反差与动作边界。
